/// <summary>
///    Service class that prints posted free text invoices (rebate-generated)
///    using Print Management destinations. Kept separate from standard
///    invoice printing to isolate this customization.
/// </summary>
class METRebateFTIPrintService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
///    Entry point called by the SysOperation framework (interactively or via batch).
/// </summary>
/// <param name="_contract">
///    The data contract carrying the CustInvoiceJour RecIds to print.
/// </param>
public void process(METRebateFTIPrintContract _contract)
{
    RecordSortedList custInvoiceJourList;

    custInvoiceJourList = this.buildCustInvoiceJourList(_contract.parmCustInvoiceTableRecIds());

    this.printFreeTextInvoices(custInvoiceJourList);
}

/// <summary>
///    Rebuilds the RecordSortedList of CustInvoiceJour from the packed RecIds.
/// </summary>
private RecordSortedList buildCustInvoiceJourList(List _custInvoiceJourRecIds)
{
    RecordSortedList custInvoiceJourList = new RecordSortedList(tableNum(CustInvoiceJour));
    custInvoiceJourList.sortOrder(fieldNum(CustInvoiceJour, RecId));

    if (_custInvoiceJourRecIds.elements() > 0)
    {
        ListEnumerator headersEnumerator =  _custInvoiceJourRecIds.getEnumerator();
        while (headersEnumerator.moveNext())
        {
            if (headersEnumerator.current())
            {
                RefRecId custInvoiceJourRecid = headersEnumerator.current();
                if (custInvoiceJourRecid)
                {
                    CustInvoiceJour custInvoiceJour = CustInvoiceJour::findRecId(custInvoiceJourRecid);

                    if (custInvoiceJour)
                    {
                        custInvoiceJourList.ins(custInvoiceJour);
                    }
                }  
            }
        }
    }

    return custInvoiceJourList;
}

/// <summary>
///    Prints the free text invoices using Print Management destinations.
/// </summary>
private void printFreeTextInvoices(RecordSortedList _custInvoiceJourList)
{
    FormLetterServiceController formLetterServiceController;
    Args                        args = new Args();

    if (!_custInvoiceJourList || !_custInvoiceJourList.len())
    {
        return;
    }

    formLetterServiceController = SalesFormLetter::construct(DocumentStatus::FreeTextInvoice);

    formLetterServiceController.usePrintManagement(true);
    formLetterServiceController.parmUseUserDefinedDestinations(false);

    args.caller(formLetterServiceController);
    args.object(_custInvoiceJourList);
    args.name(menuitemoutputstr(FreeTextInvoice));

    new MenuFunction(menuitemoutputstr(FreeTextInvoice), MenuItemType::Output).run(args);
}
